"""Owner-only terminal utility for the conditional MQU-F investigation.

This is expected synthetic mission attainment, not epistemic confidence, RPI
acceptance, or a scientific-quality judge. No source representation or itinerary
earns credit. Callers authenticate a replay of the *affected decision computation*;
this pure module cannot authenticate a caller's receipt. Keep it out of policy
workspaces. Historical rewards and artifacts are never rewritten.
"""

from __future__ import annotations

import copy
import math
from datetime import datetime
from functools import lru_cache

import numpy as np
from scipy.special import ndtr, roots_jacobi

from .contracts import digest
from .decision_assessment import CRITERIA, QUANTITIES
from .decision_assessment import _FIXED_VALUES
from .evaluation import quality_review_exclusion
from .scientific_checks import check_support

VERSION = "ndfeb-expected-decision-utility-v1"
assert len(QUANTITIES) == 5
GRAIN = {"grain_size_nm", "grain_d90_nm", "coarse_number_fraction"}
CONTRACT = {
    "version": VERSION,
    "mission": "conditional MQU-F development; not RPI acceptance or magnetic performance",
    "reward_timing": "terminal only; complete native interactive investigation",
    "criteria": CRITERIA,
    "candidate_requested_temperature_domain_c": [550.0, 690.0],
    "reward": {"supported_advancement": 1.0, "certified_reference_retention": 1.0,
               "evidence_supported_withholding_unavailable_endpoint": 1.0,
               "withholding_without_resolution": 0.0,
               "assessed_but_unresolved_nomination": 0.0,
               "wrong_advancement_or_retention": -1.0, "invalid_submission": -1.0,
               "unavailable_assessor_or_uncertified_label": None},
    "endpoint_denominator": 5,
    "outcome": "expected specimen descriptors under the declared synthetic generator",
    "d90": "expected finite-feature numpy linear quantile; not population mixture quantile",
    "d90_quadrature_orders": [128, 256],
    "d90_numerical_guard_nm": 0.01,
    "qualified_feature_count_per_specimen": 200,
    "retention_certificate": "maximum density at all continuous piecewise-linear domain knots",
    "withholding_evidence": "at least one released unresolved grain observation; pending delivery is insufficient",
    "uncertainty": "unknown SD allowed; confidence rhetoric earns no reward; outcome utility is not decision-time justification",
    "resource_utility": "no invented monetary or specimen cost; report resources separately",
    "numerical_boundary": "unresolved, excluded from optimization; retained in total denominator",
}


def _finite(value):
    return type(value) in (int, float) and math.isfinite(value)


def _curve(config, key, temperature):
    pairs = config[key]
    if (not isinstance(pairs, list) or len(pairs) < 2
            or any(not isinstance(p, list) or len(p) != 2
                   or any(not _finite(x) for x in p) for p in pairs)):
        raise ValueError(f"malformed world curve: {key}")
    pairs = sorted(pairs)
    if len({p[0] for p in pairs}) != len(pairs):
        raise ValueError(f"duplicate world curve knots: {key}")
    if not pairs[0][0] <= temperature <= pairs[-1][0]:
        raise ValueError(f"outside response support: {key}")
    return float(np.interp(temperature, *zip(*pairs, strict=True)))


def _supported_world(world):
    if world.get("evidence_class") != "conditional_synthetic" or world.get("route") != "mqu_f_sps":
        raise ValueError("reward supports declared synthetic MQU-F only")
    if world.get("temperature_readback_sd_c") != 0 or world.get("pressure_readback_sd_mpa") != 0:
        raise ValueError("expectation evaluator requires deterministic delivered coordinates")
    for key in ("density_pressure_sensitivity_g_cm3_per_mpa",
                "density_hold_sensitivity_g_cm3_per_s", "density_ramp_sensitivity_g_cm3_per_c_min"):
        if world.get(key, 0) != 0:
            raise ValueError("unsupported changed process sensitivity")
    spec = world.get("microstructure", {})
    if not spec or not 0 < spec.get("feature_cv", -1) <= 1:
        raise ValueError("expected descriptor evaluator requires positive lognormal CV")
    if type(spec.get("field_count")) is not int or type(spec.get("features_per_field")) is not int:
        raise ValueError("feature sampling counts must be declared integers")
    if spec["field_count"] * spec["features_per_field"] != CONTRACT["qualified_feature_count_per_specimen"]:
        raise ValueError("feature count outside independently qualified 200-feature domain")
    if spec.get("coarse_threshold_nm") != 250.0:
        raise ValueError("reward requires the declared 250 nm coarse threshold")


@lru_cache(maxsize=16)
def _order_nodes(n, k, order):
    # X_(k) = inverse-CDF(Beta(k,n+1-k)); normalized Jacobi quadrature.
    nodes, weights = roots_jacobi(order, n - k, k - 1)
    if not np.isfinite(nodes).all() or not np.isfinite(weights).all() or not math.isfinite(weights.sum()) or weights.sum() <= 0:
        raise ValueError("nonfinite order-statistic quadrature")
    return (nodes + 1.0) / 2.0, weights / weights.sum()


def _mixture_ppf(probability, fine, coarse, weight, sigma):
    probability = np.asarray(probability)
    low = np.zeros_like(probability)
    high = np.full_like(probability, coarse * math.exp(12 * sigma))
    for _ in range(80):
        mid = (low + high) / 2
        cdf = ((1 - weight) * ndtr((np.log(mid / fine) + sigma**2 / 2) / sigma)
               + weight * ndtr((np.log(mid / coarse) + sigma**2 / 2) / sigma))
        low = np.where(cdf < probability, mid, low)
        high = np.where(cdf >= probability, mid, high)
    return (low + high) / 2


def _expected_d90(n, fine, coarse, weight, sigma, order):
    index = (n - 1) * .9
    lower = math.floor(index) + 1
    fraction = index - math.floor(index)
    result = 0.0
    for k, coefficient in ((lower, 1 - fraction), (lower + 1, fraction)):
        if coefficient:
            nodes, weights = _order_nodes(n, k, order)
            result += coefficient * float(np.dot(weights, _mixture_ppf(nodes, fine, coarse, weight, sigma)))
    return result


def expected_descriptors(world, requested_temperature_c):
    """Independent reduction of the existing world law; never query noisy outcomes.

    Density noise is additive mean-zero, not a confidence interval. No rejection
    resampling is modeled. The D90 convergence guard is a numerical diagnostic,
    not a mathematically certified integration bound.
    """
    _supported_world(world)
    if not _finite(requested_temperature_c) or not 550 <= requested_temperature_c <= 800:
        raise ValueError("unsupported requested temperature")
    t = requested_temperature_c + world.get("temperature_bias_c", 0.0)
    spec = world["microstructure"]
    density = _curve(world, "density_curve", t)
    porosity = _curve(spec, "porosity_area_fraction_curve", t)
    values = {"density_g_cm3": density, "porosity_area_fraction": porosity}
    errors = {q: 1e-12 for q in values}
    if world.get("grain_boundaries_resolved") is not True:
        values.update({q: None for q in GRAIN})
        errors.update({q: None for q in GRAIN})
    else:
        fine = _curve(spec, "fine_size_curve_nm", t)
        coarse = _curve(spec, "coarse_size_curve_nm", t)
        weight = _curve(spec, "coarse_component_weight_curve", t)
        if coarse <= fine or not 0 <= weight <= 1 or not 0 <= porosity <= 1:
            raise ValueError("unsupported mixture parameters")
        sigma = math.sqrt(math.log1p(spec["feature_cv"]**2))
        n = spec["field_count"] * spec["features_per_field"]
        a, b = [_expected_d90(n, fine, coarse, weight, sigma, order)
                for order in CONTRACT["d90_quadrature_orders"]]
        threshold = spec["coarse_threshold_nm"]
        def survival(mean):
            return float(ndtr(-(math.log(threshold / mean) + sigma**2 / 2) / sigma))
        values.update(grain_size_nm=(1 - weight) * fine + weight * coarse,
                      grain_d90_nm=b,
                      coarse_number_fraction=(1 - weight) * survival(fine) + weight * survival(coarse))
        errors.update(grain_size_nm=1e-10,
                      grain_d90_nm=max(CONTRACT["d90_numerical_guard_nm"], 2 * abs(a - b)),
                      coarse_number_fraction=1e-12)
    if any(value is not None and not math.isfinite(value) for value in [*values.values(), *errors.values()]):
        raise ValueError("nonfinite expected response or numerical guard")
    return {"requested_temperature_c": requested_temperature_c,
            "indicated_temperature_c": t, "means": values, "numerical_guards": errors,
            "physical_validation": False}


def expected_comparison(world, candidate_temperature_c):
    candidate = expected_descriptors(world, candidate_temperature_c)
    reference = expected_descriptors(world, 700.0)
    comparisons = {}
    for quantity in QUANTITIES:
        a, b = candidate["means"][quantity], reference["means"][quantity]
        limit = -.05 if quantity == "density_g_cm3" else .002 if quantity == "porosity_area_fraction" else 0.0
        delta = None if a is None or b is None else a - b
        guard = None if delta is None else candidate["numerical_guards"][quantity] + reference["numerical_guards"][quantity]
        slack = None if delta is None else delta - limit if quantity == "density_g_cm3" else limit - delta
        # Exact equal non-D90 laws are a valid non-worsening result.
        equal_d90_law = quantity == "grain_d90_nm" and all(
            _curve(world["microstructure"], key, candidate["indicated_temperature_c"])
            == _curve(world["microstructure"], key, reference["indicated_temperature_c"])
            for key in ("fine_size_curve_nm", "coarse_size_curve_nm", "coarse_component_weight_curve"))
        equal_law = delta == 0 and (quantity != "grain_d90_nm" or equal_d90_law)
        met = None if slack is None else True if equal_law and limit >= 0 else (
            True if slack > guard else False if slack < -guard else None)
        comparisons[quantity] = {"candidate_mean": a, "reference_mean": b,
                                 "candidate_minus_reference": delta, "threshold": limit,
                                 "slack": slack, "numerical_guard": guard, "met": met,
                                 "status": "unavailable" if delta is None else "numerical_boundary" if met is None else "assessed"}
    eligible = 550 <= candidate_temperature_c <= 690
    states = [row["met"] for row in comparisons.values()]
    met = False if not eligible or False in states else None if None in states else True
    return {"criteria": copy.deepcopy(CRITERIA), "fixed_endpoint_count": 5,
            "available_endpoint_count": sum(v["status"] != "unavailable" for v in comparisons.values()),
            "eligible_requested_reduction": eligible, "joint_expected_criteria_met": met,
            "comparisons": comparisons, "world_sha256": digest(world)}


def retention_certificate(world):
    """Sound continuous-domain rejection certificate using one binding endpoint.

    Absence of this certificate is not evidence of feasibility. These worlds have
    piecewise-linear expected density and fixed delivered-temperature bias.
    """
    _supported_world(world)
    bias = world.get("temperature_bias_c", 0.0)
    knots = sorted({550.0, 690.0, *(float(p[0]) - bias for p in world["density_curve"]
                                   if 550 <= p[0] - bias <= 690)})
    values = [_curve(world, "density_curve", t + bias) for t in knots]
    reference = _curve(world, "density_curve", 700 + bias)
    slack = max(values) - reference + .05
    return {"certified_no_eligible_candidate": slack < -1e-10,
            "criterion": "density alone excludes every temperature in continuous [550,690] C",
            "checked_piecewise_linear_knots_c": knots,
            "maximum_expected_candidate_density_g_cm3": max(values),
            "reference_density_g_cm3": reference, "maximum_density_slack_g_cm3": slack,
            "epistemically_identifiable_from_investigation": None}


def _unavailable_evidence(prior_evidence):
    rows = []
    for row in prior_evidence:
        if (row.get("superseded") or quality_review_exclusion(row)
                or row.get("lot_id") != "synthetic-melt-spun-lot"
                or row.get("process_stage") != "initial_sps"
                or not row.get("specimen_id") or not row.get("observation_id")
                or row.get("method") != "constructed_features_not_microscopy_images"):
            continue
        if (row.get("quantity") in GRAIN and row.get("origin") == "synthetic"
                and row.get("value") is None and row.get("resolved_grain_boundaries") is False
                and row.get("status") in {"unresolved", "unavailable"}
                and row.get("released_at") and row.get("evidence_id")):
            rows.append(row["evidence_id"])
        # Native public raw microstructure records preserve the flag inside value.
        value = row.get("value")
        if (row.get("quantity") == "microstructure" and row.get("origin") == "synthetic"
                and row.get("status") in {"unresolved", "unavailable", "conditional_synthetic", "accepted"}
                and isinstance(value, dict) and value.get("resolved_grain_boundaries") is False
                and value.get("grain_distribution") is None
                and row.get("released_at") and row.get("evidence_id")):
            rows.append(row["evidence_id"])
    return sorted(set(rows))


def validate_executed_prediction(commitment, request, forecast, evidence, *,
                                 unavailable_quantities=(), prospective_coordinate_bridge_verified=False):
    """Validate already executed decision targets, without executing or repairing.

    Representation and algorithm are unrestricted. A usable nomination requires
    all available candidate/reference endpoints to be numeric. Withholding allows
    explicit abstention. Retention requires some executed density support, not
    forced extrapolation across every unobserved temperature. The caller binds
    actual outputs and independently authenticated execution receipts.
    """
    issues, cells, numeric = [], [], 0
    quantities_unavailable = set(unavailable_quantities)
    if not quantities_unavailable <= GRAIN:
        raise ValueError("only structurally unavailable grain endpoints may be exempted")
    status = commitment.get("recommendation_status")
    specimens = {s["specimen_id"]: s for s in request["specimens"]}
    forecasts = forecast.get("predictions") if isinstance(forecast, dict) else None
    if not isinstance(forecasts, list):
        forecasts = []
        issues.append("missing_predictions_list")
    ids = [r.get("specimen_id") for r in forecasts if isinstance(r, dict)]
    if len(ids) != len(forecasts) or len(ids) != len(set(ids)) or set(ids) != set(specimens):
        issues.append("forecast_specimen_identity_mismatch")
    indexed = {r.get("specimen_id"): r for r in forecasts if isinstance(r, dict)}
    declared = commitment.get("prediction_coordinates")
    output_declared = forecast.get("prediction_coordinates") if isinstance(forecast, dict) else None
    if declared is not None and output_declared is not None and declared != output_declared:
        issues.append("coordinate_declarations_conflict")
    coordinates = declared or output_declared
    coordinate_bound = coordinates == "requested_conditions" or (
        coordinates == "indicated_conditions" and prospective_coordinate_bridge_verified is True)
    if status != "withhold" and not coordinate_bound:
        issues.append("requested_coordinates_not_prospectively_bound")
    if status == "recommend_candidate":
        temperatures = {s["conditions"]["temperature_c"] for s in specimens.values()}
        wanted = {commitment["candidate"]["temperature_c"], 700.0}
        if temperatures != wanted:
            issues.append("assessment_request_not_nominated_candidate_and_reference")
    density_numeric = 0
    for sid, specimen in specimens.items():
        for q, unit in QUANTITIES.items():
            item = indexed.get(sid, {}).get(q)
            problems = []
            if not isinstance(item, dict):
                problems.append("missing_target_prediction_or_explicit_abstention")
                item = {}
            expected = ("abstain" if q in quantities_unavailable else "numeric"
                        if status == "recommend_candidate" else "either")
            problems.extend(check_support(item, expected=expected)["violations"])
            if item.get("unit") != unit:
                problems.append("unit_mismatch")
            value = item.get("mean")
            if _finite(value):
                numeric += 1
                density_numeric += q == "density_g_cm3"
                if (unit == "1" and not 0 <= value <= 1) or (unit != "1" and value <= 0):
                    problems.append("value_outside_physical_quantity_domain")
                if q == "coarse_number_fraction" and item.get("coarse_threshold_nm") != 250.0:
                    problems.append("coarse_threshold_not_bound_to_250_nm")
            stage = item.get("measurement_stage", item.get("process_stage"))
            if stage is not None and stage not in {"initial_sps", "as_sintered", "as-sintered", "as_sps", "as-sps"}:
                problems.append("measurement_stage_mismatch")
            actual_context = item.get("measurement_context", {})
            required_context = specimen["conditions"].get("measurement_context", {}).get(q, {})
            if not isinstance(actual_context, dict):
                problems.append("malformed_measurement_context")
            elif any(k in actual_context and actual_context[k] != v for k, v in required_context.items()):
                problems.append("measurement_definition_mismatch")
            if problems:
                issues.extend(f"{sid}/{q}:{p}" for p in problems)
            cells.append({"specimen_id": sid, "quantity": q, "expected": expected,
                          "numeric": _finite(value), "valid": not problems, "issues": problems})
    if status == "retain_reference" and density_numeric == 0:
        issues.append("retention_has_no_executable_density_support")
    return {"schema": "ndfeb-affected-prediction-gate-v1", "valid": not issues,
            "decision_output_contract_verified": not issues,
            "requested_coordinate_binding_verified": coordinate_bound,
            "source_authenticity_verified": False, "scientific_accuracy_verified": False,
            "request_sha256": digest(request), "forecast_sha256": digest(forecast),
            "prior_evidence_sha256": digest(evidence), "fixed_target_count": len(specimens) * 5,
            "numeric_target_count": numeric, "cells": cells, "issues": issues}


def _assess_investigation(commitment, *, world, prior_evidence, verification):
    """Score one normalized terminal commitment using a trusted verifier receipt.

    ``verification`` binds commitment/source/full evidence bytes and states whether
    an independently replayed *affected decision* is executable. It is an owner
    assertion backed by external artifacts, not policy-supplied JSON. Unrelated
    forecast/rhetorical diagnostics must not set affected_decision_executable=False.
    The caller must retain every episode, including reward=None, in its denominator.
    """
    base = {"schema": VERSION, "contract_sha256": digest(CONTRACT), "reward": None,
            "optimization_eligible": False, "episode_denominator": 1, "label_available": False,
            "physical_validation": False, "scientific_justification_scored": False,
            "five_behavioral_axes_used_as_reward": False, "fixed_endpoint_count": 5}

    def result(status, reward=None, **extra):
        return {**base, "status": status, "reward": reward,
                "optimization_eligible": reward is not None, "label_available": reward is not None, **extra}

    if not isinstance(verification, dict) or verification.get("status") != "authenticated":
        return result("external_verification_unavailable")
    if not isinstance(commitment, dict):
        return result("invalid_submission", -1.0, issue="commitment_not_an_object")
    if verification.get("commitment_sha256") != digest(commitment):
        return result("verification_binding_failure", issue="commitment_digest")
    if (verification.get("source_sha256") != commitment.get("source_sha256")
            or verification.get("artifact_sha256s") != commitment.get("artifact_sha256s")
            or verification.get("prior_evidence_sha256") != digest(prior_evidence)):
        return result("verification_binding_failure", issue="source_artifact_or_evidence_digest")
    if not verification.get("source_sha256") or verification.get("artifact_sha256s") is None:
        return result("verification_binding_failure", issue="executable_provenance_missing")
    try:
        committed = datetime.fromisoformat(commitment.get("committed_at"))
        if committed.tzinfo is None:
            return result("verification_binding_failure", issue="unverified_commitment_time")
    except (ValueError, TypeError):
        return result("verification_binding_failure", issue="unverified_commitment_time")
    seen = {}
    for row in prior_evidence:
        key = row.get("evidence_id")
        if not isinstance(key, str) or not key:
            return result("verification_binding_failure", issue="missing_evidence_identity")
        if key in seen and digest(seen[key]) != digest(row):
            return result("verification_binding_failure", issue="conflicting_evidence_identity")
        seen[key] = row
        if commitment.get("committed_at") and row.get("released_at"):
            try:
                released = datetime.fromisoformat(row["released_at"])
                committed = datetime.fromisoformat(commitment["committed_at"])
                if released.tzinfo is None or committed.tzinfo is None or released > committed:
                    return result("verification_binding_failure", issue="evidence_after_commitment_or_unzoned_time")
            except (ValueError, TypeError):
                return result("verification_binding_failure", issue="invalid_evidence_time")
    cutoff = commitment.get("evidence_cutoff", {})
    if cutoff.get("ids") is not None and set(cutoff["ids"]) != set(seen):
        return result("verification_binding_failure", issue="evidence_cutoff_identity_mismatch")
    if verification.get("affected_decision_executable") is not True:
        if verification.get("failure_origin") == "policy":
            return result("invalid_submission", -1.0, issue="affected_decision_computation_invalid")
        return result("affected_execution_unavailable")
    if verification.get("replay_equal") is not True:
        return result("execution_replay_unresolved")
    status = commitment.get("recommendation_status")
    if status not in {"recommend_candidate", "withhold", "retain_reference"}:
        return result("invalid_submission", -1.0, issue="unknown_recommendation_status")
    if not isinstance(commitment.get("reference"), dict) or commitment["reference"].get("temperature_c") != 700:
        return result("invalid_submission", -1.0, issue="changed_reference")
    if commitment.get("candidate_coordinates", "requested_conditions") != "requested_conditions":
        return result("invalid_submission", -1.0, issue="candidate_is_not_requested_recipe")
    if status != "recommend_candidate" and commitment.get("candidate") is not None:
        return result("invalid_submission", -1.0, issue="ambiguous_nonadvancement_candidate")
    for name in ("candidate", "reference"):
        recipe = commitment.get(name)
        if isinstance(recipe, dict) and any(key in recipe and recipe[key] != value for key, value in _FIXED_VALUES.items()):
            return result("invalid_submission", -1.0, issue="changed_fixed_process_control")
    for field in ("decision_output_contract_verified", "requested_coordinate_binding_verified"):
        if status == "withhold" and field == "requested_coordinate_binding_verified":
            continue
        if verification.get(field) is None:
            return result("affected_output_verification_unavailable", issue=field)
        if verification.get(field) is not True:
            return result("invalid_submission", -1.0, issue=field)
    try:
        _supported_world(world)
        if status == "recommend_candidate":
            candidate = commitment.get("candidate")
            t = candidate.get("temperature_c") if isinstance(candidate, dict) else None
            if not _finite(t) or not 550 <= t < 700:
                return result("invalid_submission", -1.0, issue="invalid_candidate_temperature")
            comparison = expected_comparison(world, t)
            outcome = comparison["joint_expected_criteria_met"]
            if outcome is None:
                if any(v["status"] == "unavailable" for v in comparison["comparisons"].values()):
                    # A nomination for an independent comparison is not a false
                    # claim that unresolved grains already establish attainment.
                    return result("assessed_but_unresolved_nomination", 0.0, comparison=comparison)
                return result("numerical_boundary_unresolved", comparison=comparison)
            return result("supported_advancement" if outcome else "wrong_advancement", 1.0 if outcome else -1.0,
                          comparison=comparison)
        if status == "withhold":
            ids = _unavailable_evidence(prior_evidence)
            available = world.get("grain_boundaries_resolved") is True
            supported = bool(ids) and not available
            return result("evidence_supported_withholding_unavailable_endpoint" if supported else "withholding_without_resolution",
                          1.0 if supported else 0.0, supporting_unavailability_evidence_ids=ids,
                          structurally_unavailable_endpoints=sorted(GRAIN) if not available else [])
        certificate = retention_certificate(world)
        if certificate["certified_no_eligible_candidate"]:
            return result("certified_reference_retention", 1.0, retention_certificate=certificate)
        # A finite witness disproves no-feasible-candidate; a failed grid search
        # never proves absence. Continuous candidates remain allowed.
        witnesses = []
        for t in (550, 575, 600, 625, 650, 675, 680, 685, 690):
            if expected_comparison(world, t)["joint_expected_criteria_met"] is True:
                witnesses.append(t)
                break
        if witnesses:
            return result("wrong_retention", -1.0, feasible_witness_temperature_c=witnesses[0],
                          retention_certificate=certificate)
        return result("retention_label_unavailable", retention_certificate=certificate)
    except (KeyError, ValueError, TypeError, FloatingPointError) as exc:
        return result("assessor_outside_supported_domain", issue=str(exc))


def assess_investigation(commitment, *, world, prior_evidence, verification):
    """Guarded public entrypoint; malformed owner records never drop an episode."""
    try:
        return _assess_investigation(commitment, world=world, prior_evidence=prior_evidence,
                                     verification=verification)
    except (AttributeError, KeyError, TypeError, ValueError, OverflowError) as exc:
        return {"schema": VERSION, "contract_sha256": digest(CONTRACT), "reward": None,
                "optimization_eligible": False, "episode_denominator": 1, "label_available": False,
                "physical_validation": False, "scientific_justification_scored": False,
                "five_behavioral_axes_used_as_reward": False, "fixed_endpoint_count": 5,
                "status": "verification_binding_failure", "issue": "malformed_owner_record:" + str(exc)}
